package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Lightweight mutable Memory&lt;T&gt; equivalent (generated by CSharpToJava converter).
 *
 * <p>Unlike {@link ReadOnlyMemory}, which exposes a read-only span view, this type
 * mirrors C# {@code Memory<T>}: {@link #getSpan()} returns a writable {@link Span}
 * whose writes reach the original backing array. Backed by either a String (char
 * memory) or a T[] / byte[] array slice; does not simulate lifetime semantics.</p>
 */
public final class Memory<T> {
    /** Backing storage: a String (char memory) or a T[] / byte[] array; null for default/empty. */
    private final Object backing;
    private final int start;
    private final int length;

    /** Default (empty) memory — corresponds to C# default(Memory&lt;T&gt;). */
    public Memory() {
        this.backing = null;
        this.start = 0;
        this.length = 0;
    }

    /** Mirrors Memory&lt;T&gt;.Empty. */
    @SuppressWarnings("rawtypes")
    public static final Memory Empty = new Memory<>();

    /** Mirrors Memory&lt;T&gt;.Empty as a generated static getter call. */
    @SuppressWarnings("unchecked")
    public static <T> Memory<T> getEmpty() {
        return Empty;
    }

    public Memory(T[] array) {
        this(array, 0, array == null ? 0 : array.length);
    }

    /** Primitive byte[] backing — mirrors C# byte[] → Memory&lt;byte&gt;. */
    public Memory(byte[] array) {
        this(array, 0, array == null ? 0 : array.length);
    }

    /** Primitive int[] backing — mirrors C# int[] → Memory&lt;int&gt;. */
    public Memory(int[] array) {
        this(array, 0, array == null ? 0 : array.length);
    }

    /** Primitive char[] backing — mirrors C# char[] → Memory&lt;char&gt;. */
    public Memory(char[] array) {
        this(array, 0, array == null ? 0 : array.length);
    }

    public Memory(byte[] array, int start, int length) {
        this((Object) array, start, length);
    }

    public Memory(int[] array, int start, int length) {
        this((Object) array, start, length);
    }

    public Memory(char[] array, int start, int length) {
        this((Object) array, start, length);
    }

    /** Copy constructor — allows re-wrapping a Memory without type inference issues. */
    public Memory(Memory<T> other) {
        this.backing = other.backing;
        this.start = other.start;
        this.length = other.length;
    }

    public Memory(T[] array, int start, int length) {
        this((Object) array, start, length);
    }

    private Memory(Object backing, int start, int length) {
        if (backing == null) {
            if (start != 0 || length != 0) {
                throw new IndexOutOfBoundsException("start=" + start + ", length=" + length);
            }
            this.backing = null;
            this.start = 0;
            this.length = 0;
            return;
        }
        int arrayLength = backing instanceof String s ? s.length() : java.lang.reflect.Array.getLength(backing);
        if (start < 0 || length < 0 || start + length > arrayLength) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", length=" + length + ", arrayLength=" + arrayLength);
        }
        this.backing = backing;
        this.start = start;
        this.length = length;
    }

    /** Creates a char memory over a whole string — corresponds to string.AsMemory(). */
    public static Memory<Character> fromString(String s) {
        if (s == null || s.isEmpty()) {
            return new Memory<>();
        }
        return new Memory<>(s, 0, s.length());
    }

    public int length() {
        return length;
    }

    /** Alias for length() — matches C# Memory.Length property getter translation. */
    public int getLength() {
        return length;
    }

    public boolean isEmpty() {
        return length == 0;
    }

    /** Alias for isEmpty() — matches C# Memory.IsEmpty property getter translation. */
    public boolean getIsEmpty() {
        return length == 0;
    }

    /**
     * Writable span view over this memory — mirrors C# Memory&lt;T&gt;.Span. Writes
     * through the returned span are visible in the backing array.
     */
    public Span<T> getSpan() {
        if (backing instanceof String s) {
            @SuppressWarnings("unchecked")
            T[] chars = (T[]) new Character[length];
            for (int i = 0; i < length; i++) {
                chars[i] = (T) Character.valueOf(s.charAt(start + i));
            }
            return new Span<>(chars);
        }
        if (backing instanceof byte[] bytes) {
            @SuppressWarnings("unchecked")
            Span<Integer> span = new Span<Integer>(bytes, start, length);
            return (Span<T>) (Span<?>) span;
        }
        if (backing instanceof int[] ints) {
            @SuppressWarnings("unchecked")
            Span<Integer> span = new Span<Integer>(ints, start, length);
            return (Span<T>) (Span<?>) span;
        }
        if (backing instanceof char[] chars) {
            @SuppressWarnings("unchecked")
            Span<Character> span = new Span<Character>(chars, start, length);
            return (Span<T>) (Span<?>) span;
        }
        if (backing == null) {
            @SuppressWarnings("unchecked")
            T[] empty = (T[]) new Object[0];
            return new Span<>(empty);
        }
        @SuppressWarnings("unchecked")
        T[] array = (T[]) backing;
        return new Span<>(array, start, length);
    }

    /** Mirrors C# Memory&lt;T&gt;.AsReadOnlySpan-style conversion. */
    public ReadOnlySpan<T> asReadOnlySpan() {
        return getSpan().asReadOnlySpan();
    }

    /** Mirrors C# Memory&lt;T&gt;.AsReadOnlyMemory(). */
    public ReadOnlyMemory<T> asReadOnlyMemory() {
        if (backing instanceof byte[] bytes) {
            return new ReadOnlyMemory<>(bytes, start, length);
        }
        if (backing == null) {
            return new ReadOnlyMemory<>();
        }
        return new ReadOnlyMemory<>(toArray());
    }

    public Memory<T> slice(int sliceStart) {
        return slice(sliceStart, length - sliceStart);
    }

    public Memory<T> slice(int sliceStart, int sliceLength) {
        if (sliceStart < 0 || sliceLength < 0 || sliceStart + sliceLength > length) {
            throw new IndexOutOfBoundsException(
                "start=" + sliceStart + ", length=" + sliceLength + ", memoryLength=" + length);
        }
        if (sliceLength == 0) {
            return new Memory<>();
        }
        return new Memory<>(backing, start + sliceStart, sliceLength);
    }

    /** Mirrors C# Memory&lt;T&gt;.ToArray(). */
    public T[] toArray() {
        if (backing instanceof String s) {
            @SuppressWarnings("unchecked")
            T[] chars = (T[]) new Character[length];
            for (int i = 0; i < length; i++) {
                chars[i] = (T) Character.valueOf(s.charAt(start + i));
            }
            return chars;
        }
        if (backing instanceof byte[] bytes) {
            @SuppressWarnings("unchecked")
            T[] converted = (T[]) new Integer[length];
            for (int i = 0; i < length; i++) {
                converted[i] = (T) Integer.valueOf(bytes[start + i] & 0xFF);
            }
            return converted;
        }
        if (backing instanceof int[] ints) {
            @SuppressWarnings("unchecked")
            T[] converted = (T[]) new Integer[length];
            for (int i = 0; i < length; i++) {
                converted[i] = (T) Integer.valueOf(ints[start + i]);
            }
            return converted;
        }
        if (backing instanceof char[] chars) {
            @SuppressWarnings("unchecked")
            T[] converted = (T[]) new Character[length];
            for (int i = 0; i < length; i++) {
                converted[i] = (T) Character.valueOf(chars[start + i]);
            }
            return converted;
        }
        if (backing == null) {
            @SuppressWarnings("unchecked")
            T[] empty = (T[]) new Object[0];
            return empty;
        }
        @SuppressWarnings("unchecked")
        T[] array = (T[]) backing;
        return Arrays.copyOfRange(array, start, start + length);
    }

    /** Materializes a byte-typed memory as a primitive byte[]. */
    public byte[] toByteArray() {
        if (backing == null) {
            return new byte[0];
        }
        if (backing instanceof byte[] bytes) {
            return Arrays.copyOfRange(bytes, start, start + length);
        }
        byte[] result = new byte[length];
        for (int i = 0; i < length; i++) {
            result[i] = (byte) (((Number) java.lang.reflect.Array.get(backing, start + i)).intValue() & 0xFF);
        }
        return result;
    }

    /** Mirrors C# Memory&lt;T&gt;.CopyTo(Memory&lt;T&gt;) for array / memory destinations. */
    public void copyTo(Memory<T> destination) {
        Span<T> source = getSpan();
        Span<T> target = destination.getSpan();
        int n = Math.min(length, target.length());
        for (int i = 0; i < n; i++) {
            target.set(i, source.get(i));
        }
    }

    /** Mirrors C# Memory&lt;T&gt;.CopyTo(Span&lt;T&gt;) for span destinations. */
    public void copyTo(Span<T> destination) {
        Span<T> source = getSpan();
        int n = Math.min(length, destination.length());
        for (int i = 0; i < n; i++) {
            destination.set(i, source.get(i));
        }
    }

    public boolean tryCopyTo(Memory<T> destination) {
        if (destination.length < length) {
            return false;
        }
        copyTo(destination);
        return true;
    }

    /** Mirrors C# Memory&lt;T&gt;.Clear() — zeroes the backing element range. */
    public void clear() {
        getSpan().clear();
    }

    @Override
    public String toString() {
        if (backing instanceof String s) {
            return s.substring(start, start + length);
        }
        return super.toString();
    }
}
